correct_variants:
int power_up(int base, int k) {
    int power = 1;
    for (int i = 0; i < k; i++) {
        power *= base;
    }
    return power;
}

int power_up(int base, int k) {
    int power = 1;
    int i = 0;
    while (i < k) {
        power = power * base;
        i++;
    }
    return power;
}

int power_up(int base, int k) {
    int power = 1;
    int left = k;
    while (left > 0) {
        power *= base;
        left--;
    }
    return power;
}

